"""Generate draft supporting brochures; requires reportlab. No credentials or legal attestation."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.pagesizes import A4

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'output/pdf'
OUT.mkdir(parents=True, exist_ok=True)
FONT = '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'
pdfmetrics.registerFont(TTFont('DejaVu', FONT))
pdfmetrics.registerFont(TTFont('DejaVuBold', FONT.replace('.ttf','-Bold.ttf')))
styles=getSampleStyleSheet()
for name in ['Normal','BodyText']:
 styles[name].fontName='DejaVu'; styles[name].fontSize=9; styles[name].leading=13; styles[name].spaceAfter=7
styles.add(ParagraphStyle(name='TitleFR',fontName='DejaVuBold',fontSize=24,leading=29,textColor=colors.HexColor('#17374D'),spaceAfter=10))
styles.add(ParagraphStyle(name='SectionFR',fontName='DejaVuBold',fontSize=12,leading=16,textColor=colors.HexColor('#17374D'),spaceBefore=10,spaceAfter=6))
styles.add(ParagraphStyle(name='SmallFR',fontName='DejaVu',fontSize=7.5,leading=10,spaceAfter=5))
styles.add(ParagraphStyle(name='CellFR',fontName='DejaVu',fontSize=8,leading=11))

def p(s,style='BodyText'): return Paragraph(s,styles[style])
def h(s): return p(s,'SectionFR')
def title(sub): return [p('Inklura PDF','TitleFR'),p(sub),p('PROJET POUR VALIDATION BEO PLUS - 30 OCTOBRE 2026','SmallFR'),Spacer(1,8)]
def table(rows,widths):
 t=Table([[p(escape(c),'CellFR') for c in row] for row in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E6EEF3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,-1),0.4,colors.HexColor('#CCD7DF'))]))
 return t

def footer(canvas,doc):
 canvas.setFont('DejaVu',7);canvas.setFillColor(colors.HexColor('#51616E'))
 canvas.drawString(42,29,'BEO PLUS | Inklura PDF 1.4.0 | Brouillon non signé, non déposé')
 canvas.drawRightString(A4[0]-42,29,str(doc.page))
def build(name,story):
 SimpleDocTemplate(str(OUT/name),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=38,bottomMargin=48,title='Inklura PDF - '+name,author='Préparation technique pour BEO PLUS').build(story,onFirstPage=footer,onLaterPages=footer)

s=title('Brochure commerciale - édition Mac App Store')
s += [h('Caviarder des PDF sur son Mac'),p('Inklura PDF permet de préparer une copie caviardée d’un document : importer un PDF, rechercher du texte, sélectionner les zones à masquer, relire les pages et exporter le résultat. Le document original est conservé.'),h('Usages et fonctionnement'),p('Le logiciel s’adresse aux professionnels et particuliers qui doivent retirer des informations de documents avant leur partage. Le travail sur les PDF est local au Mac ; le service de compte ne reçoit ni le contenu des documents ni leurs chemins.'),p('L’application propose des projets, le traitement de plusieurs fichiers et une assistance locale facultative. Les modèles nécessaires à cette assistance sont téléchargés séparément. Le mode manuel ne nécessite pas ces modèles.'),h('Compte et offre prévue'),p('La connexion au compte Inklura permet de consulter le solde et de gérer les crédits d’export. L’édition Mac utilise les achats intégrés Apple. Les trois packs préparés comprennent 100, 500 et 1 000 exports PDF, sans expiration des crédits Apple. Les conditions et prix sont présentés avant l’achat.'),h('Distribution'),table([['Élément','Édition concernée'],['Éditeur de distribution','BEO PLUS'],['Produit / marque','Inklura PDF / Inklura'],['Version','1.4.0 - build 1.4.56'],['Plateforme','macOS - Intel et Apple Silicon'],['Canal et territoire prévus','Mac App Store - France'],['Identifiant du produit','com.benfavre.caviard - Apple 6828817692']],[160,351]),h('État du produit'),p('Le paquet signé a été envoyé à Apple. La publication et les essais natifs sur le Mac de validation restent à finaliser. La date de mise sur le marché n’est pas arrêtée. Cette brochure décrit le produit préparé et ne constitue ni une certification ni une autorisation administrative.'),h('Confidentialité et contact'),p('Notice produit : <link href="https://outils.inklura.fr/api/inklura-pdf/privacy" color="#14638C">outils.inklura.fr/api/inklura-pdf/privacy</link><br/>Contact professionnel : contact@activ-communication.com')]
build('inklura-pdf-brochure-commerciale-projet.pdf',s)

s=title('Brochure technique - préparation du dossier de cryptologie')
s += [h('1. Identification et périmètre'),table([['Élément','Référence vérifiée'],['Application','Inklura PDF, version 1.4.0, build 1.4.56'],['Identifiants Apple','com.benfavre.caviard ; 6828817692 ; équipe 8V54BYQURB'],['Source du paquet signé','cb5cdb3f661bc0f75034178b76a8996862605db1'],['Compilation','GitHub Actions 41082263707 ; paquet universel arm64 / x86_64'],['Envoi Apple','41083245301 ; terminé le 30 octobre 2026 à 15:46 UTC']],[145,366]),p('SHA-256 du paquet :<br/>2955e874fe75fcb27ba37f56ec886eccfe16e979db85ff9d9eea28d9d470e023','SmallFR'),h('2. Architecture et flux'),p('Le processus principal Electron gère l’accès aux fichiers sélectionnés, la connexion au compte et le téléchargement des modèles. Le rendu et le traitement PDF utilisent PDF.js dans un worker. L’édition MAS applique App Sandbox ; le rendu ne dispose pas de l’intégration Node.'),p('Les PDF et leurs mots de passe d’ouverture sont traités localement. L’export produit une copie caviardée ; aucune fonction de chiffrement du PDF exporté n’est proposée. Les échanges de compte et de crédits utilisent HTTPS. La connexion interactive est ouverte dans le navigateur du système ; les achats Mac passent par StoreKit.'),p('Les bibliothèques embarquées comprennent Electron 44.4.5, PDF.js 6.3.289 et pdf-lib 1.17.1. Electron intègre BoringSSL via Chromium/Node : l’application ne repose donc pas exclusivement sur les primitives de chiffrement du système Apple.'),h('3. Usages de la cryptographie'),p('Confidentialité : déchiffrement des PDF protégés et transport HTTPS. Authentification et intégrité : protection TLS des échanges, vérification des certificats par le runtime, empreintes SHA-256 des modèles et de fichiers utilisés dans le traitement. Des UUID aléatoires servent d’identifiants ; ils ne sont pas présentés comme une fonction de chiffrement.'),p('Les clés de signature et les clés privées API Apple restent dans les systèmes de compilation ou sur le serveur de comptes. Elles ne sont pas embarquées dans l’application ni dans ce dossier. Les notifications et justificatifs d’achat Apple sont vérifiés côté serveur, hors du binaire Mac.'),PageBreak()]
s += title('Brochure technique - inventaire cryptographique')
s += [h('4. Lecture des PDF protégés'),p('Inventaire issu de PDF.js 6.3.289, fichier legacy/build/pdf.worker.mjs. Les mécanismes sont ceux des formats PDF pris en charge ; aucun algorithme propriétaire n’a été identifié dans le code applicatif.'),table([['Algorithme / mode','Taille / paramètre','Fonction'],['AES / CBC','Clé 128 ou 256 bits ; bloc 128 bits','Déchiffrement des objets PDF et opérations du gestionnaire de mot de passe.'],['RC4 / flot','Clé PDF historique, généralement 40 à 128 bits','Compatibilité de lecture des PDF anciens protégés. Pas de nouvelle offre de chiffrement RC4.'],['MD5 / hachage','NA ; sortie 128 bits','Dérivation / validation des mots de passe des formats PDF historiques et empreinte PDF.'],['SHA-256 / SHA-384 / SHA-512','NA ; sorties 256 / 384 / 512 bits','Gestion des mots de passe PDF AES-256 selon la révision du format.']],[135,145,231]),h('5. HTTPS et intégrité des téléchargements'),p('Le code de compte et de téléchargement utilise fetch dans le processus principal Electron, sans personnalisation applicative des suites TLS. Sur Electron Linux 44.4.5 de même version, le runtime annonce TLS 1.2 minimum et TLS 1.3 maximum. Cette observation ne remplace pas un relevé du binaire MAS installé.'),table([['Famille','Paramètres à reprendre / confirmer','Usage'],['AES-GCM','Clés 128 / 256 bits','Suites TLS 1.2 / 1.3 annoncées par le runtime de référence.'],['ChaCha20-Poly1305','Clé 256 bits','Suite TLS 1.3 annoncée.'],['AES-CBC avec SHA-256 / SHA-384','Clés 128 / 256 bits','Présent dans la configuration TLS de référence ; négociation effective à relever.'],['RSA / ECDSA ; ECDHE / DHE','Tailles et groupes négociés à relever sur MAS','Authentification du serveur et établissement des clés TLS selon les suites.'],['SHA-256 ; SHA-384','NA pour le hachage seul','TLS et contrôle d’intégrité des téléchargements ; SHA-256 explicite dans le code des modèles.']],[135,200,176]),p('Les paramètres réseau effectifs dépendent de la version embarquée et des serveurs. Le relevé MAS des suites/groupes, tailles de clés et certificats n’a pas encore été réalisé. Cette section est préparatoire : ne pas la présenter comme un inventaire exhaustif attesté du binaire signé.','SmallFR'),PageBreak()]
s += title('Brochure technique - preuves et validation')
s += [h('6. Gestion et accès aux informations'),p('Le mot de passe PDF est fourni par l’utilisateur au gestionnaire PDF.js pour ouvrir son fichier. Les jetons du compte sont utilisés par le contrôleur de connexion ; aucun secret Apple de distribution ou d’achat n’est livré au client. Les opérations de compilation et les services distants ne sont pas des fonctions de chiffrement à disposition de l’utilisateur.'),p('Les PDF, projets et exports demeurent sur le poste. La suppression du compte PDF porte sur le service PDF et préserve l’identité commune aux autres produits Inklura ; elle n’efface pas les fichiers locaux.'),h('7. Vérifications réalisées et limites'),p('Le paquet universel a passé les contrôles de signature, équipe, profil, sandbox, architectures, permissions de fichiers et icône. La validation en ligne Apple puis le chargement ont réussi. Ces contrôles ne constituent ni un essai installé ni une qualification réglementaire.'),p('Avant signature du dossier : confirmer les champs administratifs BEO PLUS, la qualité du fabricant et du déclarant, la date de mise sur le marché, les paramètres cryptographiques réseau du binaire MAS et le périmètre exact des opérations déclarées. Bruno a confirmé le 30 octobre qu’aucune déclaration existante ne couvre Inklura PDF.'),h('8. Traçabilité technique'),p('Sources locales : package-lock.json ; src/main.jsx (loadingTask/onPassword) ; src/PasswordDialog.jsx ; electron/account.mjs ; electron/ai-models.mjs ; electron/document-imports.mjs ; electron/main.mjs ; worker PDF.js fourni par le paquet installé. Les sources restent accessibles pour compléter les renseignements techniques.'),h('9. Références primaires'),p('Formulaire et notice ANSSI :<br/><link href="https://demarche.numerique.gouv.fr/commencer/declaration-relative-a-un-moyen-de-cryptologie" color="#14638C">Démarche officielle - déclaration relative à un moyen de cryptologie</link><br/>Notice du 31 mars 2026 ; formulaire vierge téléchargés le 30 octobre 2026.'),p('Apple :<br/><link href="https://developer.apple.com/help/app-store-connect/reference/app-information/export-compliance-documentation-for-encryption" color="#14638C">Export compliance documentation for encryption</link><br/>Le questionnaire observé pour les algorithmes standard hors du système Apple et la distribution en France demande le document français.'),p('Electron :<br/><link href="https://www.electronjs.org/docs/latest/api/environment-variables" color="#14638C">Environment Variables - différence BoringSSL / OpenSSL</link>'),h('Statut du document'),p('Projet technique pour relecture par BEO PLUS. Aucun formulaire ni attestation signé n’a été déposé. Ce document ne remplace pas l’attestation du déclarant et n’établit pas une exemption ou une autorisation de l’ANSSI.')]
build('inklura-pdf-brochure-technique-projet.pdf',s)
print('Generated two draft brochures in',OUT)
